class TimeoutErrorWithData(Exception):
    """
    A timeout has occurred, data was read so far.
    """

    def __init__(self, data, **kwargs):
        super(TimeoutErrorWithData, self).__init__(**kwargs)
        self.data = data

    def __str__(self):
        return "data=%r" % self.data

    def __repr__(self):
        return "TimeoutErrorWithData(data=%r)" % self.data
